local a={}local b={top=true,bottom=true,left=true,right=true,front=true,back=true}function a.setOutput(c,d,e)assert(b[d],"Invalid redstone output side: "..tostring(d))assert(type(e)=="boolean","Redstone output state must be boolean")if c==nil or c==""or c=="computer"then redstone.setOutput(d,e)return end;local f=peripheral.wrap(c)assert(f,"Redstone peripheral not found: "..tostring(c))assert(type(f.setOutput)=="function","Peripheral does not provide setOutput: "..tostring(c))f.setOutput(d,e)end;return a
